  ('b7615bc6-ad48-5dc6-b58a-58c6bff6cee5'::uuid, '33124', 'David Zook', '2022-06-13'::date, '2023-10-13'::date, 'Quit - Gave no notice. Terrible attendance'),
  ('fd2932d5-994b-549a-92ad-8e812cf35af7'::uuid, '37430', 'Charles Vallo', '2023-07-06'::date, '2023-10-23'::date, 'Quit - Gave no notice. Decent driver'),
  ('fdfc17b3-c656-5e7c-9c41-87c8e34ae3d1'::uuid, '37077', 'Mauricio Orozco Castaneda', '2023-03-13'::date, '2023-11-03'::date, 'Quit - Gave 3 days notice. Decent driver.'),
  ('71ba432a-3706-56ed-acdf-90fb209f0bd4'::uuid, '35639', 'Mike Hopkins', '2021-05-11'::date, '2023-11-06'::date, 'Term - Positive random drug test - Cocaine'),
  ('94ba4b9c-3973-5203-ad31-4f8359e7143f'::uuid, '37712', 'Wayne Bol', '2023-11-27'::date, '2023-11-28'::date, 'Quit - after 1 day of training')
) as v(id, emp, name, hire, term, notes)
where not exists (
  select 1 from public.driver_gone_entries g
  where g.termination_date = v.term
    and ((v.emp is not null and g.employee_number = v.emp) or lower(trim(g.name)) = lower(v.name))
)
on conflict (id) do nothing;

select extract(year from termination_date)::int as gone_year, count(*)
from public.driver_gone_entries group by 1 order by 1 desc;
